/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// The infinitive.
    Infinitive,
    /// The non-past: present for imperfective verbs, future for perfective ones (the imperfective future `będę czytać` is a phrase).
    NonPast(Person, Number),
    /// The past tense.
    Past(Person, Agreement),
    /// The conditional.
    Conditional(Person, Agreement),
    /// The imperative (one-word forms; the first person singular and the third persons are `niech` + present, a phrase).
    Imperative(Person, Number),
    /// The impersonal past (`czytano`).
    Impersonal,
    /// An adjectival participle's citation form; decline it with `adjective`.
    Participle(Participle),
    /// An adverbial participle.
    AdverbialParticiple(AdverbialParticiple),
    /// The verbal noun (`czytanie`).
    AlNoun,
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        let cell = match self {
            Cell::Infinitive => cell::INFINITIVE,
            Cell::NonPast(Person::First, Number::Singular) => cell::NON_PAST_1_SG,
            Cell::NonPast(Person::First, Number::Plural) => cell::NON_PAST_1_PL,
            Cell::NonPast(Person::Second, Number::Singular) => cell::NON_PAST_2_SG,
            Cell::NonPast(Person::Second, Number::Plural) => cell::NON_PAST_2_PL,
            Cell::NonPast(Person::Third, Number::Singular) => cell::NON_PAST_3_SG,
            Cell::NonPast(Person::Third, Number::Plural) => cell::NON_PAST_3_PL,
            Cell::Past(Person::First, Agreement::Masculine) => cell::PAST_1_M,
            Cell::Past(Person::First, Agreement::Feminine) => cell::PAST_1_F,
            Cell::Past(Person::First, Agreement::Neuter) => cell::PAST_1_N,
            Cell::Past(Person::First, Agreement::Virile) => cell::PAST_1_VIR,
            Cell::Past(Person::First, Agreement::Nonvirile) => cell::PAST_1_NVIR,
            Cell::Past(Person::Second, Agreement::Masculine) => cell::PAST_2_M,
            Cell::Past(Person::Second, Agreement::Feminine) => cell::PAST_2_F,
            Cell::Past(Person::Second, Agreement::Neuter) => cell::PAST_2_N,
            Cell::Past(Person::Second, Agreement::Virile) => cell::PAST_2_VIR,
            Cell::Past(Person::Second, Agreement::Nonvirile) => cell::PAST_2_NVIR,
            Cell::Past(Person::Third, Agreement::Masculine) => cell::PAST_3_M,
            Cell::Past(Person::Third, Agreement::Feminine) => cell::PAST_3_F,
            Cell::Past(Person::Third, Agreement::Neuter) => cell::PAST_3_N,
            Cell::Past(Person::Third, Agreement::Virile) => cell::PAST_3_VIR,
            Cell::Past(Person::Third, Agreement::Nonvirile) => cell::PAST_3_NVIR,
            Cell::Conditional(Person::First, Agreement::Masculine) => cell::CONDITIONAL_1_M,
            Cell::Conditional(Person::First, Agreement::Feminine) => cell::CONDITIONAL_1_F,
            Cell::Conditional(Person::First, Agreement::Neuter) => cell::CONDITIONAL_1_N,
            Cell::Conditional(Person::First, Agreement::Virile) => cell::CONDITIONAL_1_VIR,
            Cell::Conditional(Person::First, Agreement::Nonvirile) => cell::CONDITIONAL_1_NVIR,
            Cell::Conditional(Person::Second, Agreement::Masculine) => cell::CONDITIONAL_2_M,
            Cell::Conditional(Person::Second, Agreement::Feminine) => cell::CONDITIONAL_2_F,
            Cell::Conditional(Person::Second, Agreement::Neuter) => cell::CONDITIONAL_2_N,
            Cell::Conditional(Person::Second, Agreement::Virile) => cell::CONDITIONAL_2_VIR,
            Cell::Conditional(Person::Second, Agreement::Nonvirile) => cell::CONDITIONAL_2_NVIR,
            Cell::Conditional(Person::Third, Agreement::Masculine) => cell::CONDITIONAL_3_M,
            Cell::Conditional(Person::Third, Agreement::Feminine) => cell::CONDITIONAL_3_F,
            Cell::Conditional(Person::Third, Agreement::Neuter) => cell::CONDITIONAL_3_N,
            Cell::Conditional(Person::Third, Agreement::Virile) => cell::CONDITIONAL_3_VIR,
            Cell::Conditional(Person::Third, Agreement::Nonvirile) => cell::CONDITIONAL_3_NVIR,
            Cell::Imperative(Person::First, Number::Singular) => cell::IMPERATIVE_1_SG,
            Cell::Imperative(Person::First, Number::Plural) => cell::IMPERATIVE_1_PL,
            Cell::Imperative(Person::Second, Number::Singular) => cell::IMPERATIVE_2_SG,
            Cell::Imperative(Person::Second, Number::Plural) => cell::IMPERATIVE_2_PL,
            Cell::Imperative(Person::Third, Number::Singular) => cell::IMPERATIVE_3_SG,
            Cell::Imperative(Person::Third, Number::Plural) => cell::IMPERATIVE_3_PL,
            Cell::Impersonal => cell::IMPERSONAL,
            Cell::Participle(Participle::Active) => cell::PARTICIPLE_ACT,
            Cell::Participle(Participle::Passive) => cell::PARTICIPLE_PASS,
            Cell::AdverbialParticiple(AdverbialParticiple::Contemporary) => {
                cell::ADVERBIAL_PARTICIPLE_CONTEMP
            }
            Cell::AdverbialParticiple(AdverbialParticiple::Anterior) => {
                cell::ADVERBIAL_PARTICIPLE_ANT
            }
            Cell::AlNoun => cell::VERBAL_NOUN,
        };
        cell as usize
    }
}

